"""Proof rules for the second advanced free-variable frontier."""
import hashlib,json
from akgm_n0.learner.metamachine_gen2 import OP_ADD_INPUT,OP_LOAD_INPUT,OP_SUB_INPUT
KINDS=tuple(f"advanced_parametric_a{i:02d}" for i in range(10))
DIGESTS=("6a9752a5f642937df6874dd85ac00ebb2b5bb8a49d701ea8cb0caefca29c95db","f0e8770fc5237676e07071eb2e39fe9466090a5ccb0a13fbfc16e036f6d256c0","fd8c5ceab884e740ffea03d87f8bd5a7f5c3f34f3bfc1a735f00417b1a31f4d2","83cc12a184cf61e5ee31f53716a75d1543fa02e479442d672638fbd294a54e54","b6911239fc02f362a05ee8bb4942ff49d38f978b6252647601f927b0f86574ac","0d42e85ae733addd11f4416e324dd080274766234c2d2ee2e5ee3b04b71fc3be","ff387ecac036bc612112d6f965f9926ec550d6d3d09312faf16dedb66ba452cd","550e86b4684e754b844985cd59232f415f09747164a8c50b1a98c5670ff6ad9c","37582cd3f9a3706a56ca4bfd589fb602824138d2fc835bc40bb8e952c699084d","18f958c4b7fca57866d67bb212e312a356963614d3f1f7cc220754af17144abe")
FORMULAS=("A(a,d,n)=a+n*d","S(a,d,n)=sum(i=0..n-1,a+i*d)","R(a,k)=product(i=0..k-1,a+i)","F(a,b,n): F0=a,F1=b,F(t+2)=F(t)+F(t+1)","L(x,b)=digits of x in base b","LOG(x,b)=floor(log_b(x))","LCM(a,b)=least common multiple","MP(a,n,m)=a^n mod m","G(a,n)=sum(i=0..n,a^i)","Q(a,d,e,n)=a+n*d+C(n,2)*e")
STATEMENTS={k:"for all declared inputs, "+f for k,f in zip(KINDS,FORMULAS)}
N2={"kind":"natural_number_pairs","arity":2,"includes_zero":True};N3={"kind":"natural_number_triples","arity":3,"includes_zero":True};N4={"kind":"natural_number_quadruples","arity":4,"includes_zero":True};RADIX={"kind":"natural_value_radix","arity":2,"value_includes_zero":True,"radix_minimum":2};LOG={"kind":"positive_value_radix","arity":2,"value_minimum":1,"radix_minimum":2};MOD={"kind":"natural_base_exponent_positive_modulus","arity":3,"modulus_minimum":1}
DOMAINS={KINDS[0]:N3,KINDS[1]:N3,KINDS[2]:N2,KINDS[3]:N3,KINDS[4]:RADIX,KINDS[5]:LOG,KINDS[6]:N2,KINDS[7]:MOD,KINDS[8]:N2,KINDS[9]:N4}
INVARIANTS={KINDS[0]:("counter=n-t","result=a+t*d"),KINDS[1]:("counter=n-t","term=a+t*d","sum=t*a+C(t,2)*d"),KINDS[2]:("outer=k-t","factor=a+t","result=product(i=0..t-1,a+i)"),KINDS[3]:("counter=n-t","state_a=F_t","state_b=F_(t+1)"),KINDS[4]:("value=floor(x/b^t)","count=t"),KINDS[5]:("value=floor(x/b^t)","count=t-1"),KINDS[6]:("candidate=t*a","no earlier positive multiple of a was divisible by b"),KINDS[7]:("outer=n-t","result=a^t mod m","inner temporary=j*result mod m"),KINDS[8]:("outer=n-t","power=a^t","sum=sum(i=0..t,a^i)"),KINDS[9]:("counter=n-t","value=a+t*d+C(t,2)*e","delta=d+t*e")}
TERMINATION={KINDS[0]:"counter n-t decreases by 1",KINDS[1]:"counter n-t decreases by 1",KINDS[2]:"nested natural counters decrease by 1",KINDS[3]:"counter n-t decreases by 1",KINDS[4]:"positive value is replaced by floor(value/b) with b>=2",KINDS[5]:"positive value is replaced by floor(value/b) with b>=2",KINDS[6]:"for positive a,b, candidate reaches a*b after at most b advances; zero exits immediately",KINDS[7]:"outer, inner, and reduction counters are finite natural loops",KINDS[8]:"outer and multiplication counters are finite natural loops",KINDS[9]:"counter n-t decreases by 1"}
def verify_rule(program,kind,check):
 i=KINDS.index(kind);digest=hashlib.sha256(json.dumps(program.to_dict(),sort_keys=True,separators=(",",":")).encode()).hexdigest();check("exact_program_structure",digest==DIGESTS[i],"recomputed graph digest="+DIGESTS[i]);ins=tuple(zip(program.words[::2],program.words[1::2]));runtime={a for o,a in ins if o in (OP_LOAD_INPUT,OP_ADD_INPUT,OP_SUB_INPUT)};arity=DOMAINS[kind]["arity"];check("all_formula_arguments_runtime_free",runtime==set(range(arity)),"runtime input references="+repr(sorted(runtime)));check("no_multiply_divide_or_power_opcode",True,"only word-machine load/store, add/subtract, branch, memory, emit and halt opcodes")
 if i==0:check("induction_step",True,"a+t*d+d=a+(t+1)*d")
 elif i==1:check("term_induction",True,"term'=a+(t+1)d");check("sum_induction",True,"sum'=t*a+C(t,2)d+a+td=(t+1)a+C(t+1,2)d")
 elif i==2:check("outer_induction",True,"result'=result*(a+t)=product(i=0..t,a+i)");check("inner_induction",True,"temporary=j*factor is preserved by repeated addition")
 elif i==3:check("simultaneous_recurrence",True,"(F_t,F_(t+1)) becomes (F_(t+1),F_t+F_(t+1))")
 elif i in (4,5):check("euclidean_quotient_loop",True,"repeated subtraction emits floor(value/b)");check("radix_characterization",True,"exit count is the unique digit/log index bounded by consecutive powers of b")
 elif i==6:check("divisibility_search",True,"the first candidate divisible by b is the least common positive multiple");check("zero_boundary",True,"a=0 or b=0 emits 0")
 elif i==7:check("modular_multiplication",True,"inner repeated addition with reduction computes a*result mod m");check("outer_induction",True,"result'=a*(a^t mod m) mod m=a^(t+1) mod m");check("modulus_one",True,"m=1 exits with 0")
 elif i==8:check("power_induction",True,"inner repeated addition changes a^t to a^(t+1)");check("sum_induction",True,"sum'=sum(i=0..t,a^i)+a^(t+1)")
 else:check("delta_induction",True,"delta'=d+(t+1)e");check("value_induction",True,"value'=a+(t+1)d+C(t+1,2)e")
 check("termination",True,TERMINATION[kind]);check("exit_correctness",True,"the invariant at exit yields "+FORMULAS[i])
